options.styles:
.staging-source {
  box-sizing: border-box;
  width: 100%;
  font-family: var(--font-sans, Inter, Arial, sans-serif);
  color: var(--color-text-primary, #1f2933);
}
.staging-source-row {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(300px, 420px) 84px;
  align-items: center;
  gap: 20px;
  min-height: 64px;
  padding: 12px 16px;
  border: 1px solid var(--color-border-weak, #d0d5dd);
  border-radius: 6px;
  background: var(--color-background-primary, #fff);
}
.staging-source-label {
  font-size: 13px;
  font-weight: 600;
}
.staging-source-hint,
.staging-source-message {
  margin-top: 3px;
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  line-height: 1.35;
}
.staging-source-message.error {
  color: #b42318;
}
.staging-source-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-width: 0;
  margin: 0;
  padding: 3px;
  border: 1px solid var(--color-border-medium, #b8c0cc);
  border-radius: 6px;
  background: var(--color-background-secondary, #f2f4f7);
}
.staging-source-options legend {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.staging-source-option {
  min-width: 0;
  cursor: pointer;
}
.staging-source-option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.staging-source-option span {
  display: block;
  min-height: 32px;
  padding: 8px 10px;
  border-radius: 4px;
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  white-space: nowrap;
}
.staging-source-option input:checked + span {
  color: #fff;
  background: #2563eb;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.16);
}
.staging-source-option input:focus-visible + span,
.staging-source-action:focus-visible {
  outline: 2px solid #1570ef;
  outline-offset: 2px;
}
.staging-source-option input:disabled + span {
  cursor: not-allowed;
  opacity: 0.55;
}
.staging-source-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.staging-source-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--color-border-medium, #b8c0cc);
  border-radius: 4px;
  color: var(--color-text-primary, #1f2933);
  background: var(--color-background-primary, #fff);
  font-family: inherit;
  font-size: 15px;
  cursor: pointer;
}
.staging-source-action.save {
  border-color: #2563eb;
  color: #fff;
  background: #2563eb;
}
.staging-source-action:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
@media (max-width: 720px) {
  .staging-source-row {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .staging-source-actions {
    justify-content: flex-start;
  }
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
.staging-source:where(.dark) { color-scheme: dark; color: var(--color-text-primary, #e4e4ec); }
*:where(.staging-source.dark) .staging-source-row { border-color: var(--color-border-weak, #34373d); background: var(--color-background-primary, #181b1f); }
*:where(.staging-source.dark) .staging-source-hint,
*:where(.staging-source.dark) .staging-source-message { color: var(--color-text-secondary, #b0b0be); }
*:where(.staging-source.dark) .staging-source-message.error { color: #ff7383; }
*:where(.staging-source.dark) .staging-source-options { border-color: var(--color-border-medium, #34373d); background: var(--color-background-secondary, #22252b); }
*:where(.staging-source.dark) .staging-source-option span { color: var(--color-text-secondary, #b0b0be); }
*:where(.staging-source.dark) .staging-source-action { border-color: var(--color-border-medium, #34373d); color: var(--color-text-primary, #e4e4ec); background: var(--color-background-primary, #181b1f); }

