(() => {
  const HOST = '/cpms';
  const KEY = 'ct_fan.cws_controller';
  const panel = document.getElementById('ctFanCwsOutdoorTargets');
  if (!panel) return;

  const tbody = panel.querySelector('tbody');
  const settingsPanel = panel.querySelector('.outdoor-targets-settings');
  const controllerInputs = [...panel.querySelectorAll('.controller-field')];
  const addButton = panel.querySelector('.add');
  const cancelButton = panel.querySelector('.cancel');
  const saveButton = panel.querySelector('.save');
  const message = panel.querySelector('.outdoor-targets-message');
  const frames = typeof context !== 'undefined' && Array.isArray(context.data) ? context.data : [];
  const rows = Array.isArray(frames[0]) ? frames[0] : frames;
  const parameter = rows.find((row) => row?.key === KEY);

  const parseController = (value) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    if (typeof value !== 'string') return undefined;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : undefined;
    } catch {
      return undefined;
    }
  };

  let controller = parseController(parameter?.value);
  let settings = {};
  let ranges = [];
  let busy = false;

  const copySettings = (value) => ({
    enabled: value?.enabled !== false,
    defaultHz: Number(value?.defaultHz),
    minHz: Number(value?.minHz),
    maxHz: Number(value?.maxHz),
    stepHz: Number(value?.stepHz),
    target: Number(value?.target),
    deadband: Number(value?.deadband),
    holdMs: Number(value?.holdMs),
    dwellMs: Number(value?.dwellMs),
  });

  const copyRanges = (value) =>
    Array.isArray(value)
      ? value.map(({ min, max, target }) => ({ min: Number(min), max: Number(max), target: Number(target) }))
      : [];

  const normalized = (value) =>
    value
      .map(({ min, max, target }) => ({ min: Number(min), max: Number(max), target: Number(target) }))
      .sort((a, b) => a.min - b.min || a.max - b.max);

  const setMessage = (text, isError = false) => {
    message.textContent = text;
    message.classList.toggle('error', isError);
  };

  const validationError = () => {
    const numericSettings = [
      settings.defaultHz,
      settings.minHz,
      settings.maxHz,
      settings.stepHz,
      settings.target,
      settings.deadband,
      settings.holdMs,
      settings.dwellMs,
    ];
    if (numericSettings.some((value) => !Number.isFinite(value))) return 'Every controller setting requires a numeric value.';
    if (settings.minHz >= settings.maxHz) return 'Minimum speed must be lower than maximum speed.';
    if (settings.defaultHz < settings.minHz || settings.defaultHz > settings.maxHz) {
      return 'Fixed speed must be within the configured speed range.';
    }
    if (settings.stepHz <= 0) return 'Speed step must be greater than zero.';
    if (settings.deadband < 0) return 'Deadband cannot be negative.';
    if (settings.holdMs < 0 || settings.dwellMs < 0) return 'Hold and dwell cannot be negative.';

    const sorted = normalized(ranges);
    if (sorted.some((range) => !Number.isFinite(range.min) || !Number.isFinite(range.max) || !Number.isFinite(range.target))) {
      return 'Every range requires numeric minimum, maximum, and target values.';
    }
    if (sorted.some((range) => range.min >= range.max)) return 'Each minimum must be lower than its maximum.';
    if (sorted.some((range, index) => index > 0 && range.min < sorted[index - 1].max)) {
      return 'Outdoor temperature ranges cannot overlap.';
    }
    return '';
  };

  const isChanged = () => {
    const current = { ...settings, targetByOutdoorTemp: normalized(ranges) };
    const original = {
      ...copySettings(controller),
      targetByOutdoorTemp: normalized(copyRanges(controller?.targetByOutdoorTemp)),
    };
    return JSON.stringify(current) !== JSON.stringify(original);
  };

  const renderSettings = () => {
    controllerInputs.forEach((input) => {
      const value = settings[input.dataset.field];
      if (input.type === 'checkbox') {
        input.checked = Boolean(value);
      } else {
        const scale = Number(input.dataset.scale ?? 1);
        input.value = Number.isFinite(value) ? value / scale : '';
      }
    });
  };

  const renderRows = () => {
    tbody.innerHTML = '';
    if (ranges.length === 0) {
      const row = document.createElement('tr');
      row.innerHTML = '<td class="outdoor-targets-empty" colspan="4">No outdoor temperature ranges configured.</td>';
      tbody.appendChild(row);
      return;
    }

    ranges.forEach((range, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="min" type="number" step="0.1" value="${range.min}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="max" type="number" step="0.1" value="${range.max}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="target" type="number" step="0.1" value="${range.target}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><button class="outdoor-targets-action delete" data-index="${index}" type="button" title="Delete range" aria-label="Delete range">&#10005;</button></td>
      `;
      tbody.appendChild(row);
    });
  };

  const renderState = () => {
    const ready = Boolean(controller && parameter);
    const error = ready ? validationError() : '';
    const changed = ready && isChanged();
    panel.querySelectorAll('.controller-field, .outdoor-targets-table .outdoor-targets-input, .delete').forEach((element) => {
      element.disabled = busy || !ready;
    });
    addButton.disabled = busy || !ready;
    cancelButton.disabled = busy || !changed;
    saveButton.disabled = busy || !changed || Boolean(error);
    if (!busy && error) setMessage(error, true);
    if (!busy && !error && ready) {
      setMessage(settings.enabled ? 'Automatic CWS temperature control enabled.' : 'Fixed fan speed control enabled.');
    }
  };

  const render = () => {
    renderSettings();
    renderRows();
    renderState();
  };

  const responseBody = async (response) => {
    const text = await response.text();
    if (!text) return undefined;
    try {
      return JSON.parse(text);
    } catch {
      return text;
    }
  };

  const errorMessage = (body, response) =>
    typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`;

  const bindEvent = (element, eventName, handler) => {
    const handlers = element.__outdoorTargetHandlers ?? {};
    if (handlers[eventName]) element.removeEventListener(eventName, handlers[eventName]);
    handlers[eventName] = handler;
    element.__outdoorTargetHandlers = handlers;
    element.addEventListener(eventName, handler);
  };

  bindEvent(settingsPanel, 'input', (event) => {
    const input = event.target.closest('.controller-field');
    if (!input) return;
    if (input.type === 'checkbox') {
      settings[input.dataset.field] = input.checked;
    } else {
      const scale = Number(input.dataset.scale ?? 1);
      settings[input.dataset.field] = input.value === '' ? NaN : Number(input.value) * scale;
    }
    renderState();
  });

  bindEvent(tbody, 'input', (event) => {
    const input = event.target.closest('.outdoor-targets-input');
    if (!input) return;
    ranges[Number(input.dataset.index)][input.dataset.field] = input.value === '' ? NaN : Number(input.value);
    renderState();
  });

  bindEvent(tbody, 'click', (event) => {
    const button = event.target.closest('.delete');
    if (!button || busy) return;
    ranges.splice(Number(button.dataset.index), 1);
    render();
  });

  bindEvent(addButton, 'click', () => {
    const sorted = normalized(ranges);
    const min = sorted.length > 0 && Number.isFinite(sorted.at(-1).max) ? sorted.at(-1).max : 25;
    ranges.push({ min, max: min + 1, target: Number(settings.target) });
    render();
    tbody.querySelector(`input[data-index="${ranges.length - 1}"]`)?.focus();
  });

  bindEvent(cancelButton, 'click', () => {
    settings = copySettings(controller);
    ranges = copyRanges(controller.targetByOutdoorTemp);
    render();
  });

  bindEvent(saveButton, 'click', async () => {
    const error = validationError();
    if (error || !isChanged()) return;

    let reason = '';
    while (!reason) {
      const input = window.prompt(
        'Confirm saving cooling tower fan CWS controller settings.\n\nEnter a remark for this change:',
        reason,
      );
      if (input === null) return;
      reason = input.trim();
      if (!reason) window.alert('Remark is required.');
    }

    const nextRanges = normalized(ranges);

    busy = true;
    setMessage('Saving...');
    renderState();

    try {
      const nextController = { ...controller, ...settings, targetByOutdoorTemp: nextRanges };
      const response = await fetch(`${HOST}/params/value`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: parameter.scope,
          equipmentKind: parameter.equipment_kind,
          equipmentId: parameter.equipment_id,
          key: KEY,
          value: nextController,
          reason,
        }),
      });
      const body = await responseBody(response);
      if (!response.ok) throw new Error(errorMessage(body, response));

      controller = nextController;
      settings = copySettings(nextController);
      ranges = copyRanges(nextRanges);
      setMessage('Controller settings saved.');
      if (typeof context !== 'undefined' && context.grafana?.refresh) context.grafana.refresh();
    } catch (error) {
      setMessage(`Unable to save parameter: ${error.message}`, true);
    } finally {
      busy = false;
      renderState();
    }
  });

  if (controller && parameter) {
    settings = copySettings(controller);
    ranges = copyRanges(controller.targetByOutdoorTemp);
    render();
  } else {
    setMessage(`Invalid or missing ${KEY} query result`, true);
    render();
  }
})();

options.helpers:
// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

options.styles:
.outdoor-targets {
  box-sizing: border-box;
  width: 100%;
  font-family: var(--font-sans, Inter, Arial, sans-serif);
  color: var(--color-text-primary, #1f2933);
}
.outdoor-targets-card {
  border: 1px solid var(--color-border-weak, #d0d5dd);
  border-radius: 6px;
  background: var(--color-background-primary, #fff);
}
.outdoor-targets-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-weak, #d0d5dd);
}
.outdoor-targets-title {
  font-size: 16px;
  font-weight: 700;
}
.outdoor-targets-hint,
.outdoor-targets-message {
  margin-top: 3px;
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  line-height: 1.35;
}
.outdoor-targets-message.error {
  color: #b42318;
}
.outdoor-targets .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.outdoor-targets-settings {
  display: grid;
  grid-template-columns: repeat(5, minmax(120px, 1fr));
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-border-weak, #d0d5dd);
}
.outdoor-targets-field {
  min-width: 0;
}
.outdoor-targets-field > span {
  display: block;
  margin-bottom: 5px;
  color: var(--color-text-secondary, #667085);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}
.outdoor-targets-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.outdoor-targets-toggle input {
  width: 16px;
  height: 16px;
  margin: 0;
}
.outdoor-targets-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--color-border-weak, #d0d5dd);
}
.outdoor-targets-section-title {
  font-size: 13px;
  font-weight: 600;
}
.outdoor-targets-table-wrap {
  overflow-x: auto;
}
.outdoor-targets-table {
  width: 100%;
  min-width: 560px;
  border-collapse: collapse;
  table-layout: fixed;
}
.outdoor-targets-table th,
.outdoor-targets-table td {
  padding: 9px 12px;
  border-bottom: 1px solid var(--color-border-weak, #eaecf0);
  text-align: left;
  vertical-align: middle;
}
.outdoor-targets-table th {
  color: var(--color-text-secondary, #667085);
  background: var(--color-background-secondary, #f2f4f7);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}
.outdoor-targets-table td {
  font-size: 13px;
}
.outdoor-targets-table th:last-child,
.outdoor-targets-table td:last-child {
  width: 52px;
  text-align: center;
}
.outdoor-targets-input-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
}
.outdoor-targets-input {
  box-sizing: border-box;
  width: 100%;
  min-width: 90px;
  height: 34px;
  padding: 6px 8px;
  border: 1px solid var(--color-border-medium, #b8c0cc);
  border-radius: 4px;
  color: var(--color-text-primary, #1f2933);
  background: var(--color-background-primary, #fff);
  font-family: inherit;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.outdoor-targets-input:focus-visible,
.outdoor-targets-toggle input:focus-visible,
.outdoor-targets-action:focus-visible {
  outline: 2px solid #1570ef;
  outline-offset: 2px;
}
.outdoor-targets-unit {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  white-space: nowrap;
}
.outdoor-targets-empty {
  padding: 18px 12px;
  color: var(--color-text-secondary, #667085);
  text-align: center;
}
.outdoor-targets-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
}
.outdoor-targets-actions {
  display: flex;
  gap: 8px;
}
.outdoor-targets-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--color-border-medium, #b8c0cc);
  border-radius: 4px;
  color: var(--color-text-primary, #1f2933);
  background: var(--color-background-primary, #fff);
  font-family: inherit;
  font-size: 16px;
  cursor: pointer;
}
.outdoor-targets-action.save,
.outdoor-targets-action.add {
  border-color: #2563eb;
  color: #fff;
  background: #2563eb;
}
.outdoor-targets-action.delete {
  color: #b42318;
}
.outdoor-targets-action:disabled,
.outdoor-targets-input:disabled,
.outdoor-targets-toggle input:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
@media (max-width: 720px) {
  .outdoor-targets-header,
  .outdoor-targets-footer {
    align-items: stretch;
  }
  .outdoor-targets-header {
    flex-direction: column;
  }
  .outdoor-targets-settings {
    grid-template-columns: repeat(2, minmax(120px, 1fr));
  }
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
.outdoor-targets:where(.dark) { color-scheme: dark; color: var(--color-text-primary, #e4e4ec); }
*:where(.outdoor-targets.dark) .outdoor-targets-card { border-color: var(--color-border-weak, #34373d); background: var(--color-background-primary, #181b1f); }
*:where(.outdoor-targets.dark) .outdoor-targets-header,
*:where(.outdoor-targets.dark) .outdoor-targets-settings,
*:where(.outdoor-targets.dark) .outdoor-targets-section-header { border-bottom-color: var(--color-border-weak, #34373d); }
*:where(.outdoor-targets.dark) .outdoor-targets-hint,
*:where(.outdoor-targets.dark) .outdoor-targets-message,
*:where(.outdoor-targets.dark) .outdoor-targets-field > span,
*:where(.outdoor-targets.dark) .outdoor-targets-unit,
*:where(.outdoor-targets.dark) .outdoor-targets-empty { color: var(--color-text-secondary, #b0b0be); }
*:where(.outdoor-targets.dark) .outdoor-targets-message.error,
*:where(.outdoor-targets.dark) .outdoor-targets-action.delete { color: #ff7383; }
*:where(.outdoor-targets.dark) .outdoor-targets-table th,
*:where(.outdoor-targets.dark) .outdoor-targets-table td { border-bottom-color: var(--color-border-weak, #2a2d33); }
*:where(.outdoor-targets.dark) .outdoor-targets-table th { color: var(--color-text-secondary, #b0b0be); background: var(--color-background-secondary, #22252b); }
*:where(.outdoor-targets.dark) .outdoor-targets-input,
*:where(.outdoor-targets.dark) .outdoor-targets-action { border-color: var(--color-border-medium, #34373d); color: var(--color-text-primary, #e4e4ec); background: var(--color-background-primary, #181b1f); }

options.afterRender:
(async () => {
        const HOST = '/cpms';
        const panel = document.getElementById('leadLagPriority');
        if (!panel) return;
        const removeEventListeners = (element) => {
            const cleanElement = element.cloneNode(true);
            element.replaceWith(cleanElement);
            return cleanElement;
        };

        // default list
        const rowsByType = {
            chiller: [{ equipment_id: 'chiller1' }, { equipment_id: 'chiller2' }, { equipment_id: 'chiller3' }],
            cooling_tower: [{ equipment_id: 'ct1' }, { equipment_id: 'ct2' }, { equipment_id: 'ct3' }],
        };
        const definitions = {
            chiller: {
                label: 'Chiller',
                modeKey: 'chiller.priority_mode',
                orderKey: 'chiller.priority_order',
                excludedKey: 'chiller.priority_excluded_ids',
                anchorIdKey: 'chiller.priority_anchor_id',
                anchorEffectiveAtKey: 'chiller.priority_anchor_effective_at',
                previousAnchorIdKey: 'chiller.priority_previous_anchor_id',
                previousAnchorEffectiveAtKey: 'chiller.priority_previous_anchor_effective_at',
            },
            cooling_tower: {
                label: 'Cooling tower',
                modeKey: 'cooling_tower.priority_mode',
                orderKey: 'cooling_tower.priority_order',
                excludedKey: 'cooling_tower.priority_excluded_ids',
                anchorIdKey: 'cooling_tower.priority_anchor_id',
                anchorEffectiveAtKey: 'cooling_tower.priority_anchor_effective_at',
                previousAnchorIdKey: 'cooling_tower.priority_previous_anchor_id',
                previousAnchorEffectiveAtKey: 'cooling_tower.priority_previous_anchor_effective_at',
            },
        };
        const roles = ['Lead', 'Lag', 'Standby'];
        const MALAYSIA_OFFSET_MS = 8 * 60 * 60 * 1000;
        const DAY_MS = 24 * 60 * 60 * 1000;
        const nextMalaysiaMidnight = (now = Date.now()) =>
            (Math.floor((now + MALAYSIA_OFFSET_MS) / DAY_MS) + 1) * DAY_MS - MALAYSIA_OFFSET_MS;
        const malaysiaDateTime = new Intl.DateTimeFormat('en-MY', {
            timeZone: 'Asia/Kuala_Lumpur',
            dateStyle: 'medium',
            timeStyle: 'short',
        });
        const parseValue = (value) => {
            if (typeof value !== 'string') return value;
            try {
                return JSON.parse(value);
            } catch {
                return value;
            }
        };
        const displayName = (id) => {
            const match = String(id).match(/^(chiller|ct)(\d+)$/i);
            return match
                ? `${match[1].toLowerCase() === 'ct' ? 'CT' : 'CH'}-${match[2].padStart(2, '0')}`
                : String(id).toUpperCase();
        };
        const responseBody = async (response) => {
            const text = await response.text();
            if (!text) return undefined;
            try {
                return JSON.parse(text);
            } catch {
                return text;
            }
        };
        let globalParams;
        try {
            const response = await fetch(`${HOST}/params/all`);
            const body = await responseBody(response);
            if (!response.ok) {
                throw new Error(
                    typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`
                );
            }
            globalParams = body?.global ?? {};
        } catch (error) {
            panel.querySelectorAll('.lead-lag-message').forEach((message) => {
                message.textContent = `Load failed: ${error.message}`;
                message.classList.add('error');
            });
            return;
        }
        const valueOf = (key) => parseValue(globalParams[key]);

        Object.entries(definitions).forEach(([type, definition]) => {
            const card = panel.querySelector(`[data-type="${type}"]`);
            const fieldset = removeEventListeners(card.querySelector('.lead-lag-mode'));
            const list = removeEventListeners(card.querySelector('.lead-lag-list'));
            const message = card.querySelector('.lead-lag-message');
            const anchor = card.querySelector('.lead-lag-anchor');
            const anchorSelect = anchor ? removeEventListeners(anchor.querySelector('.lead-lag-anchor-select')) : null;
            const anchorStatus = anchor?.querySelector('.lead-lag-anchor-status');
            const buttons = [...card.querySelectorAll('button')].map(removeEventListeners);
            const cancel = buttons.find((button) => button.classList.contains('cancel'));
            const save = buttons.find((button) => button.classList.contains('save'));
            const equipmentIds = rowsByType[type]
                .map((row) => row?.equipment_id)
                .filter(Boolean)
                .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true }));
            let currentMode = valueOf(definition.modeKey) === 'MANUAL' ? 'MANUAL' : 'AUTO';
            const storedOrder = valueOf(definition.orderKey);
            const configuredOrder = Array.isArray(storedOrder)
                ? storedOrder.filter((id) => equipmentIds.includes(id))
                : [];
            let currentOrder = configuredOrder.length
                ? [...new Set([...configuredOrder, ...equipmentIds])]
                : [...equipmentIds];
            const storedExcluded = valueOf(definition.excludedKey);
            let currentExcluded = Array.isArray(storedExcluded)
                ? [...new Set(storedExcluded.filter((id) => equipmentIds.includes(id)))]
                : [];
            const storedAnchorId = definition.anchorIdKey ? valueOf(definition.anchorIdKey) : null;
            const storedAnchorEffectiveAt = definition.anchorEffectiveAtKey
                ? valueOf(definition.anchorEffectiveAtKey)
                : null;
            let currentAnchorId = equipmentIds.includes(storedAnchorId) ? storedAnchorId : null;
            let currentAnchorEffectiveAt = Number.isFinite(storedAnchorEffectiveAt) ? storedAnchorEffectiveAt : null;
            const storedPreviousAnchorId = definition.previousAnchorIdKey
                ? valueOf(definition.previousAnchorIdKey)
                : null;
            const storedPreviousAnchorEffectiveAt = definition.previousAnchorEffectiveAtKey
                ? valueOf(definition.previousAnchorEffectiveAtKey)
                : null;
            let currentPreviousAnchorId = equipmentIds.includes(storedPreviousAnchorId) ? storedPreviousAnchorId : null;
            let currentPreviousAnchorEffectiveAt = Number.isFinite(storedPreviousAnchorEffectiveAt)
                ? storedPreviousAnchorEffectiveAt
                : null;
            let draftOrder = [...currentOrder];
            let draftExcluded = [...currentExcluded];
            let draftAnchorId = '';
            let busy = false;
            if (anchorSelect) {
                anchorSelect.innerHTML = [
                    `<option value="">Select ${definition.label.toLowerCase()}</option>`,
                    ...equipmentIds.map((id) => `<option value="${id}">${displayName(id)}</option>`),
                ].join('');
            }
            const selectedMode = () => card.querySelector('input:checked')?.value;
            const changed = () =>
                selectedMode() !== currentMode ||
                draftOrder.join() !== currentOrder.join() ||
                draftExcluded.join() !== currentExcluded.join() ||
                draftAnchorId !== '';
            const setMessage = (text, error = false) => {
                message.textContent = text;
                message.classList.toggle('error', error);
            };
            const selectMode = (mode) =>
                card.querySelectorAll('input[type="radio"]').forEach((input) => {
                    input.checked = input.value === mode;
                });
            const render = () => {
                const manual = selectedMode() === 'MANUAL';
                const includedOrder = draftOrder.filter((id) => !draftExcluded.includes(id));
                if (draftExcluded.includes(draftAnchorId)) draftAnchorId = '';
                if (anchor) anchor.hidden = manual;
                if (anchorSelect) {
                    anchorSelect.disabled = manual || busy || equipmentIds.length === 0;
                    anchorSelect.value = draftAnchorId;
                    [...anchorSelect.options].forEach((option) => {
                        option.disabled = option.value !== '' && draftExcluded.includes(option.value);
                    });
                }
                if (anchorStatus) {
                    const pending = currentAnchorEffectiveAt !== null && currentAnchorEffectiveAt > Date.now();
                    anchorStatus.textContent =
                        currentAnchorId && currentAnchorEffectiveAt !== null
                            ? `${pending ? 'Scheduled' : 'Rotation anchored'}: ${displayName(currentAnchorId)} · ${malaysiaDateTime.format(currentAnchorEffectiveAt)}`
                            : 'No operator-selected rotation anchor.';
                }
                list.innerHTML = draftOrder.length
                    ? draftOrder
                          .map((id, index) => {
                              const name = displayName(id);
                              const excluded = draftExcluded.includes(id);
                              const priorityIndex = includedOrder.indexOf(id);
                              const upDisabled = !manual || busy || index === 0 ? 'disabled' : '';
                              const downDisabled = !manual || busy || index === draftOrder.length - 1 ? 'disabled' : '';
                              return `<li class="lead-lag-item${excluded ? ' excluded' : ''}">
                    <span class="lead-lag-rank">${excluded ? '—' : priorityIndex + 1}</span>
                    <span class="lead-lag-name">${name}</span>
                    <span class="lead-lag-role">${excluded ? 'Excluded' : (roles[priorityIndex] ?? 'Standby')}</span>
                    <label class="lead-lag-include">
                      <input type="checkbox" class="include" data-id="${id}"
                        ${excluded ? '' : 'checked'} ${busy ? 'disabled' : ''} /> Include
                    </label>
                    <span class="lead-lag-controls">
                      <button class="lead-lag-action move" type="button" data-index="${index}"
                        data-direction="up" title="Move up" aria-label="Move ${name} up"
                        ${upDisabled}>&#8593;</button>
                      <button class="lead-lag-action move" type="button" data-index="${index}"
                        data-direction="down" title="Move down" aria-label="Move ${name} down"
                        ${downDisabled}>&#8595;</button>
                    </span>
                  </li>`;
                          })
                          .join('')
                    : '<li class="lead-lag-empty">No configured equipment found.</li>';
                fieldset.disabled = busy || equipmentIds.length === 0;
                cancel.disabled = busy || !changed();
                save.disabled = busy || !changed() || includedOrder.length === 0;
            };
            card.querySelectorAll('input[type="radio"]').forEach((input) => input.addEventListener('change', render));
            anchorSelect?.addEventListener('change', () => {
                draftAnchorId = anchorSelect.value;
                render();
            });
            list.addEventListener('click', (event) => {
                const button = event.target.closest('.move');
                if (!button) return;
                const index = Number(button.dataset.index);
                const target = button.dataset.direction === 'up' ? index - 1 : index + 1;
                if (target < 0 || target >= draftOrder.length) return;
                [draftOrder[index], draftOrder[target]] = [draftOrder[target], draftOrder[index]];
                render();
            });
            list.addEventListener('change', (event) => {
                const input = event.target.closest('.include');
                if (!input) return;
                draftExcluded = input.checked
                    ? draftExcluded.filter((id) => id !== input.dataset.id)
                    : [...draftExcluded, input.dataset.id];
                render();
            });
            cancel.addEventListener('click', () => {
                draftOrder = [...currentOrder];
                draftExcluded = [...currentExcluded];
                draftAnchorId = '';
                selectMode(currentMode);
                render();
            });
            save.addEventListener('click', async () => {
                const mode = selectedMode();
                let reason = '';
                while (!reason) {
                    const input = window.prompt(
                        `Confirm ${definition.label.toLowerCase()} priority change.\n\nEnter a remark:`,
                        reason
                    );
                    if (input === null) return;
                    reason = input.trim();
                    if (!reason) window.alert('Remark is required.');
                }
                busy = true;
                setMessage('Saving...');
                render();
                try {
                    const values = {
                        [definition.modeKey]: mode,
                        [definition.orderKey]: draftOrder,
                        [definition.excludedKey]: draftExcluded,
                    };
                    let scheduledAnchorEffectiveAt = currentAnchorEffectiveAt;
                    if (mode === 'AUTO' && definition.anchorIdKey && draftAnchorId) {
                        const currentIsActive =
                            currentAnchorId &&
                            currentAnchorEffectiveAt !== null &&
                            currentAnchorEffectiveAt <= Date.now();
                        const activeAnchorId = currentIsActive ? currentAnchorId : currentPreviousAnchorId;
                        const activeAnchorEffectiveAt = currentIsActive
                            ? currentAnchorEffectiveAt
                            : currentPreviousAnchorEffectiveAt;
                        scheduledAnchorEffectiveAt = nextMalaysiaMidnight();
                        values[definition.anchorIdKey] = draftAnchorId;
                        values[definition.anchorEffectiveAtKey] = scheduledAnchorEffectiveAt;
                        values[definition.previousAnchorIdKey] = activeAnchorId;
                        values[definition.previousAnchorEffectiveAtKey] = activeAnchorEffectiveAt;
                    }
                    const response = await fetch(`${HOST}/params/global`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            values,
                            reason,
                        }),
                    });
                    const body = await responseBody(response);
                    if (!response.ok)
                        throw new Error(
                            typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`
                        );
                    currentMode = mode;
                    currentOrder = [...draftOrder];
                    currentExcluded = [...draftExcluded];
                    if (draftAnchorId) {
                        const currentIsActive =
                            currentAnchorId &&
                            currentAnchorEffectiveAt !== null &&
                            currentAnchorEffectiveAt <= Date.now();
                        currentPreviousAnchorId = currentIsActive ? currentAnchorId : currentPreviousAnchorId;
                        currentPreviousAnchorEffectiveAt = currentIsActive
                            ? currentAnchorEffectiveAt
                            : currentPreviousAnchorEffectiveAt;
                        currentAnchorId = draftAnchorId;
                        currentAnchorEffectiveAt = scheduledAnchorEffectiveAt;
                        draftAnchorId = '';
                    }
                    setMessage(`Current mode: ${mode === 'AUTO' ? 'Automatic daily rotation' : 'Manual priority'}`);
                    if (typeof context !== 'undefined' && context.grafana?.refresh) context.grafana.refresh();
                } catch (error) {
                    setMessage(`Save failed: ${error.message}`, true);
                } finally {
                    busy = false;
                    render();
                }
            });
            selectMode(currentMode);
            setMessage(
                equipmentIds.length
                    ? `Current mode: ${currentMode === 'AUTO' ? 'Automatic daily rotation' : 'Manual priority'}`
                    : 'No configured equipment found.',
                equipmentIds.length === 0
            );
            render();
        });
    })();

