.lead-lag {
        box-sizing: border-box;
        width: 100%;
        font-family: var(--font-sans, Inter, Arial, sans-serif);
        color: var(--color-text-primary, #1f2933);
    }
    .lead-lag-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 12px;
    }
    .lead-lag-card {
        overflow: hidden;
        border: 1px solid var(--color-border-weak, #d0d5dd);
        border-radius: 6px;
        background: var(--color-background-primary, #fff);
    }
    .lead-lag-header {
        padding: 12px 16px;
        border-bottom: 1px solid var(--color-border-weak, #d0d5dd);
    }
    .lead-lag-title {
        font-size: 16px;
        font-weight: 700;
    }
    .lead-lag-hint,
    .lead-lag-message {
        margin-top: 3px;
        color: var(--color-text-secondary, #667085);
        font-size: 12px;
        line-height: 1.35;
    }
    .lead-lag-message.error {
        color: #b42318;
    }
    .lead-lag-mode {
        display: grid;
        grid-template-columns: 1fr 1fr;
        margin: 12px 16px;
        padding: 3px;
        border: 1px solid var(--color-border-medium, #b8c0cc);
        border-radius: 6px;
        background: var(--color-background-secondary, #f2f4f7);
    }
    .lead-lag-mode legend {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        white-space: nowrap;
    }
    .lead-lag-option {
        min-width: 0;
        cursor: pointer;
    }
    .lead-lag-option input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
    }
    .lead-lag-option span {
        display: block;
        min-height: 32px;
        padding: 8px 10px;
        border-radius: 4px;
        color: var(--color-text-secondary, #667085);
        font-size: 12px;
        font-weight: 700;
        line-height: 16px;
        text-align: center;
    }
    .lead-lag-option input:checked + span {
        color: #fff;
        background: #2563eb;
        box-shadow: 0 1px 2px rgba(16, 24, 40, 0.16);
    }
    .lead-lag-option input:focus-visible + span,
