        padding: 0 16px 6px;
        color: var(--color-text-secondary, #667085);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.3px;
        text-transform: uppercase;
    }
    .lead-lag-anchor {
        display: grid;
        grid-template-columns: minmax(130px, 1fr) minmax(150px, 1fr);
        gap: 8px 12px;
        align-items: center;
        margin: 0 16px 12px;
        padding: 10px 12px;
        border: 1px solid var(--color-border-weak, #eaecf0);
        border-radius: 4px;
        background: var(--color-background-secondary, #f8fafc);
    }
    .lead-lag-anchor[hidden] {
        display: none;
    }
    .lead-lag-anchor-label {
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.3px;
        text-transform: uppercase;
    }
    .lead-lag-anchor-select {
        box-sizing: border-box;
        width: 100%;
        height: 34px;
        padding: 6px 8px;
        border: 1px solid var(--color-border-medium, #b8c0cc);
        border-radius: 4px;
        color: var(--color-text-primary, #1f2933);
        background: var(--color-background-primary, #fff);
        font-family: inherit;
        font-size: 13px;
    }
    .lead-lag-anchor-select:focus-visible {
        outline: 2px solid #1570ef;
        outline-offset: 2px;
    }
    .lead-lag-anchor-status {
        grid-column: 1 / -1;
        color: var(--color-text-secondary, #667085);
        font-size: 13px;
        line-height: 1.35;
    }
    .lead-lag-list {
        margin: 0;
        padding: 0;
        border-top: 1px solid var(--color-border-weak, #eaecf0);
        list-style: none;
    }
    .lead-lag-item {
        display: grid;
        grid-template-columns: 28px minmax(90px, 1fr) 72px 76px auto;
        gap: 8px;
        align-items: center;
        min-height: 46px;
        padding: 6px 16px;
        border-bottom: 1px solid var(--color-border-weak, #eaecf0);
        font-size: 13px;
    }
    .lead-lag-rank {
        color: var(--color-text-secondary, #667085);
        font-variant-numeric: tabular-nums;
        text-align: center;
    }
    .lead-lag-name {
        font-size: 13px;
        font-weight: 700;
    }
    .lead-lag-role {
        color: var(--color-text-secondary, #667085);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.3px;
        text-transform: uppercase;
    }
