        background: var(--color-background-secondary, #f8fafc);
    }
    .lead-lag-item.excluded .lead-lag-rank,
    .lead-lag-item.excluded .lead-lag-name {
        color: var(--color-text-secondary, #667085);
    }
    .lead-lag-include {
        display: inline-flex;
        gap: 6px;
        align-items: center;
        color: var(--color-text-secondary, #667085);
        font-size: 12px;
        cursor: pointer;
    }
    .lead-lag-include input {
        width: 16px;
        height: 16px;
        margin: 0;
        accent-color: #2563eb;
    }
    .lead-lag-controls,
    .lead-lag-actions {
        display: flex;
        gap: 8px;
    }
    .lead-lag-action {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 34px;
        height: 34px;
        padding: 0;
        border: 1px solid var(--color-border-medium, #b8c0cc);
        border-radius: 4px;
        color: var(--color-text-primary, #1f2933);
        background: var(--color-background-primary, #fff);
        font-family: inherit;
        font-size: 15px;
        cursor: pointer;
    }
    .lead-lag-action.save {
        border-color: #2563eb;
        color: #fff;
        background: #2563eb;
    }
    .lead-lag-action:disabled,
    .lead-lag-option input:disabled + span {
        cursor: not-allowed;
