    }
    .lead-lag-footer {
        display: flex !important;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 10px 16px;
    }
    .lead-lag-empty {
        padding: 18px 16px;
        color: var(--color-text-secondary, #667085);
        font-size: 13px;
        text-align: center;
    }
    @media (max-width: 800px) {
        .lead-lag-grid {
            grid-template-columns: 1fr;
        }
    }
    @media (max-width: 480px) {
        .lead-lag-item {
            grid-template-columns: 24px 1fr 72px auto;
        }
        .lead-lag-role {
            display: none;
        }
    }

