options.afterRender:
(async () => {
  const HOST = '/cpms';
  const DURATION_KEY = 'plant.warmup_duration_ms';
  const STAGE_KEY = 'plant.warmup_chiller_setpoint_stage_duration_ms';
  const CAPACITY_KEY = 'plant.warmup_chiller_capacity_limit_pct';
  const INITIAL_SETPOINT_KEY = 'plant.warmup_initial_chiller_setpoint';
  const INTERMEDIATE_SETPOINT_KEY = 'plant.warmup_intermediate_chiller_setpoint';
  const FINAL_SETPOINT_KEY = 'plant.warmup_chiller_setpoint';
  const panel = document.getElementById('warmupTiming');
  if (!panel) return;

  const removeEventListeners = (element) => {
    const cleanElement = element.cloneNode(true);
    element.replaceWith(cleanElement);
    return cleanElement;
  };
  const inputs = [...panel.querySelectorAll('.warmup-timing-input')].map(removeEventListeners);
  const capacityInput = panel.querySelector('.capacity');
  const initialSetpointInput = panel.querySelector('.initial-setpoint');
  const intermediateSetpointInput = panel.querySelector('.intermediate-setpoint');
  const finalSetpointInput = panel.querySelector('.final-setpoint');
  const durationInput = panel.querySelector('.duration');
  const stageInput = panel.querySelector('.stage');
  const cancel = removeEventListeners(panel.querySelector('.cancel'));
  const save = removeEventListeners(panel.querySelector('.save'));
  const message = panel.querySelector('.warmup-timing-message');
  const rule = panel.querySelector('.warmup-timing-rule');
  const responseBody = async (response) => {
    const text = await response.text();
    if (!text) return undefined;
    try {
      return JSON.parse(text);
    } catch {
      return text;
    }
  };
  const errorText = (body, response) =>
    typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`;
  const minutes = (milliseconds) => Number(milliseconds) / 60000;
  const milliseconds = (minutesValue) => Math.round(Number(minutesValue) * 60000);
  const displayMinutes = (value) => Number(value.toFixed(3)).toString();

  let current = {};
  let busy = false;

  const values = () => ({
    capacity: Number(capacityInput.value),
    initialSetpoint: Number(initialSetpointInput.value),
    intermediateSetpoint: Number(intermediateSetpointInput.value),
    finalSetpoint: Number(finalSetpointInput.value),
    duration: Number(durationInput.value),
    stage: Number(stageInput.value),
  });
  const validationError = () => {
    const { capacity, initialSetpoint, intermediateSetpoint, finalSetpoint, duration, stage } = values();
    if (!Number.isFinite(capacity) || capacity <= 0 || capacity > 100) {
      return 'Capacity limit must be greater than 0% and no more than 100%.';
    }
    const validSetpoints = [initialSetpoint, intermediateSetpoint, finalSetpoint].every(
      (value) => Number.isFinite(value) && value >= 4 && value <= 18,
    );
    if (!validSetpoints) {
      return 'Warm-up setpoints must be between 4°C and 18°C.';
    }
    if (initialSetpoint < intermediateSetpoint || intermediateSetpoint < finalSetpoint) {
      return 'Setpoints must descend from initial to intermediate to final.';
    }
    if (!Number.isFinite(duration) || duration <= 0) return 'Warm-up duration must be greater than zero.';
    if (!Number.isFinite(stage) || stage <= 0) return 'Stage duration must be greater than zero.';
    if (stage > duration / 3) return 'Stage duration cannot exceed one third of warm-up duration.';
    return '';
  };
  const changed = () => {
    const value = values();
    return value.capacity !== current.capacity ||
      value.initialSetpoint !== current.initialSetpoint ||
      value.intermediateSetpoint !== current.intermediateSetpoint ||
      value.finalSetpoint !== current.finalSetpoint ||
      milliseconds(value.duration) !== current.duration ||
      milliseconds(value.stage) !== current.stage;
  };
  const setMessage = (text, error = false) => {
    message.textContent = text;
    message.classList.toggle('error', error);
  };
  const setBusy = (nextBusy) => {
    busy = nextBusy;
    inputs.forEach((input) => { input.disabled = busy; });
    render();
  };
  const phaseRange = (start, end) => `${displayMinutes(start)}–${displayMinutes(end)} min`;
  const render = () => {
    const { initialSetpoint, intermediateSetpoint, finalSetpoint, duration, stage } = values();
    const validNumbers = Number.isFinite(duration) && Number.isFinite(stage) && duration > 0 && stage > 0;
    panel.querySelector('.phase-initial-value').textContent = Number.isFinite(initialSetpoint)
      ? `${initialSetpoint}°C`
      : '—';
    panel.querySelector('.phase-intermediate-value').textContent = Number.isFinite(intermediateSetpoint)
      ? `${intermediateSetpoint}°C`
      : '—';
    panel.querySelector('.phase-final-value').textContent = Number.isFinite(finalSetpoint)
      ? `${finalSetpoint}°C`
      : '—';
    panel.querySelector('.phase-initial').textContent = validNumbers ? phaseRange(0, stage) : '—';
    panel.querySelector('.phase-intermediate').textContent = validNumbers ? phaseRange(stage, stage * 2) : '—';
    panel.querySelector('.phase-final').textContent = validNumbers ? phaseRange(stage * 2, stage * 3) : '—';
    const error = validationError();
    rule.textContent = error || `Final phase completes at ${validNumbers ? displayMinutes(stage * 3) : '—'} min.`;
    rule.classList.toggle('warmup-timing-error', Boolean(error));
    cancel.disabled = busy || !changed();
    save.disabled = busy || !changed() || Boolean(error);
  };
  const reset = () => {
    capacityInput.value = current.capacity;
    initialSetpointInput.value = current.initialSetpoint;
    intermediateSetpointInput.value = current.intermediateSetpoint;
    finalSetpointInput.value = current.finalSetpoint;
    durationInput.value = displayMinutes(minutes(current.duration));
    stageInput.value = displayMinutes(minutes(current.stage));
    setMessage('Values loaded.');
    render();
  };

  try {
    const response = await fetch(`${HOST}/params/all`);
    const body = await responseBody(response);
    if (!response.ok) throw new Error(errorText(body, response));
    current = {
      capacity: Number(body?.global?.[CAPACITY_KEY] ?? 60),
      initialSetpoint: Number(body?.global?.[INITIAL_SETPOINT_KEY] ?? 12),
      intermediateSetpoint: Number(body?.global?.[INTERMEDIATE_SETPOINT_KEY] ?? 10.5),
      finalSetpoint: Number(body?.global?.[FINAL_SETPOINT_KEY] ?? 9),
      duration: Number(body?.global?.[DURATION_KEY] ?? 30 * 60_000),
      stage: Number(body?.global?.[STAGE_KEY] ?? 10 * 60_000),
    };
    reset();
    inputs.forEach((input) => { input.disabled = false; });
    render();
  } catch (error) {
    setMessage(`Load failed: ${error.message}`, true);
    return;
  }

  inputs.forEach((input) => input.addEventListener('input', render));
  cancel.addEventListener('click', reset);
  save.addEventListener('click', async () => {
    const error = validationError();
    if (error) {
      setMessage(error, true);
      return;
    }

    let reason = '';
    while (!reason) {
      const answer = prompt('Remark for this change:', reason);
      if (answer === null) return;
      reason = answer.trim();
      if (!reason) alert('Remark is required.');
    }

    const value = values();
    setBusy(true);
    setMessage('Saving...');
    try {
      const response = await fetch(`${HOST}/params/global`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          values: {
            [CAPACITY_KEY]: value.capacity,
            [INITIAL_SETPOINT_KEY]: value.initialSetpoint,
            [INTERMEDIATE_SETPOINT_KEY]: value.intermediateSetpoint,
            [FINAL_SETPOINT_KEY]: value.finalSetpoint,
            [DURATION_KEY]: milliseconds(value.duration),
            [STAGE_KEY]: milliseconds(value.stage),
          },
          reason,
        }),
      });
      const body = await responseBody(response);
      if (!response.ok) throw new Error(errorText(body, response));
      current = {
        capacity: value.capacity,
        initialSetpoint: value.initialSetpoint,
        intermediateSetpoint: value.intermediateSetpoint,
        finalSetpoint: value.finalSetpoint,
        duration: milliseconds(value.duration),
        stage: milliseconds(value.stage),
      };
      setMessage('Updated successfully.');
    } catch (error) {
      setMessage(`Save failed: ${error.message}`, true);
    } finally {
      setBusy(false);
    }
  });
})();

