options.afterRender:
(async () => {
  const HOST = '/cpms';
  const KEY = 'ct_valve.close_reseat_enabled';
  const root = document.getElementById('ctValveCloseRecovery');
  if (!root) return;
  const body = root.querySelector('tbody');
  const message = root.querySelector('.ct-valve-recovery-message');
  const names = {
    ct1ValveIn: 'CT-1 Inlet Valve', ct1ValveOut: 'CT-1 Outlet Valve',
    ct2ValveIn: 'CT-2 Inlet Valve', ct2ValveOut: 'CT-2 Outlet Valve',
    ct3ValveIn: 'CT-3 Inlet Valve', ct3ValveOut: 'CT-3 Outlet Valve',
  };
  const rows = Array.isArray(context.data)
    ? context.data.filter((row) => row?.scope === 'EQUIPMENT' && row?.equipment_kind === 'VALVE' && row?.key === KEY)
    : [];
  rows.sort((a, b) => String(a.equipment_id).localeCompare(String(b.equipment_id), undefined, { numeric: true }));
  body.replaceChildren();

  const responseBody = async (response) => {
    const text = await response.text();
    if (!text) return undefined;
    try { return JSON.parse(text); } catch { return text; }
  };
  const errorText = (value, response) => typeof value === 'string'
    ? value
    : value?.error || value?.message || ('HTTP ' + response.status);
  const setMessage = (text, error = false) => {
    message.textContent = text;
    message.classList.toggle('error', error);
  };

  for (const row of rows) {
    const tr = document.createElement('tr');
    const nameCell = document.createElement('td');
    const name = document.createElement('div');
    name.className = 'ct-valve-name';
    name.textContent = names[row.equipment_id] || row.equipment_id;
    const id = document.createElement('div');
    id.className = 'ct-valve-id';
    id.textContent = row.equipment_id;
    nameCell.append(name, id);

    const valueCell = document.createElement('td');
    const label = document.createElement('label');
    label.className = 'ct-valve-toggle';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = row.value === true;
    const state = document.createElement('span');
    state.className = 'ct-valve-state';
    const renderState = () => { state.textContent = input.checked ? 'Enabled' : 'Disabled'; };
    renderState();
    label.append(input, state);
    valueCell.append(label);

    const actionCell = document.createElement('td');
    const save = document.createElement('button');
    save.className = 'ct-valve-save';
    save.type = 'button';
    save.textContent = 'Save';
    save.disabled = true;
    actionCell.append(save);
    tr.append(nameCell, valueCell, actionCell);
    body.append(tr);

    let original = row.value === true;
    input.addEventListener('change', () => { renderState(); save.disabled = input.checked === original; });
    save.addEventListener('click', async () => {
      let reason = '';
      while (!reason) {
        const answer = prompt('Remark for this change:', reason);
        if (answer === null) return;
        reason = answer.trim();
        if (!reason) alert('Remark is required.');
      }
      input.disabled = true;
      save.disabled = true;
      setMessage('Saving ' + row.equipment_id + '...');
      try {
        const response = await fetch(HOST + '/params/value', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            scope: 'EQUIPMENT', equipmentKind: 'VALVE', equipmentId: row.equipment_id,
            key: KEY, value: input.checked, reason,
          }),
        });
        const result = await responseBody(response);
        if (!response.ok) throw new Error(errorText(result, response));
        original = input.checked;
        row.value = input.checked;
        setMessage(row.equipment_id + ' updated successfully.');
        context.grafana.refresh();
      } catch (error) {
        input.checked = original;
        renderState();
        setMessage('Save failed: ' + error.message, true);
      } finally {
        input.disabled = false;
        save.disabled = true;
      }
    });
  }
  setMessage(rows.length ? 'Valve settings loaded.' : 'No CT valve recovery parameters found.', rows.length === 0);
})();

