options.afterRender:
import("/esm/datatables.net-bs5").then(({ default: DataTable }) => {
  $(document).ready(async function () {
    const HOST = "/cpms";
    let table;
    let isEdit = false;

    const GROUP = "Pump & Fan Controllers";
    const grouping = JSON.parse(context.grafana.replaceVariables("$grouping"));

    let rawData = context.data[0];
    let telemeryData = context.data[1].pop() ?? {};

    const allowedKeys = grouping[GROUP] ? Object.keys(grouping[GROUP]) : [];
    const keyOrder = new Map(allowedKeys.map((key, index) => [key, index]));

    const data = Array.isArray(rawData)
      ? rawData.filter(item => item && item.key && allowedKeys.includes(item.key))
      : [];

    table = new DataTable("#ptp-table-7", {
      retrieve: true,
      searching: false,
      paging: false,
      pageLength: 10,
      ordering: false,
      lengthChange: false,
      info: false,
      data: data ?? [],
      order: [
        [0, "asc"],
      ],
      columns: [
        // 1. Setting Name Column
        {
          data: null,
          className: "col-setting",
          render: function (data, type, row) {
            if (type === "sort" || type === "type") return keyOrder.get(row.key) ?? Number.MAX_SAFE_INTEGER;
            return `
            <div class="ptp-label">${grouping[GROUP][row.key] ?? "-"}</div>
            <div class="ptp-hint">${row.description ?? ""}</div>
          `;
          }
        },
        // 2. Enabled Column
        {
          data: "value.enabled",
          className: "col-value col-enabled dt-body-center",
          // width: "54px",
          orderable: false,
          render: function (data, type, row) {
            const enabled = data !== false;
            const disabled = row.isEditingRow ? "" : "disabled";
            return `<input class="ptp-field" data-field="enabled" data-type="boolean" type="checkbox" style="width:16px;height:16px" ${enabled ? "checked" : ""} ${disabled}>`;
          }
        },
        // 3. Fixed Hz Column
        {
          data: "value.defaultHz",
          className: "col-value",
          render: function (data, type, row) {
            const value = data ?? 35;
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="defaultHz" placeholder="Enter Numerical Value" type="number" step="0.1" style="width:70px" value="${value}">`
              : `${value}`;
          }
        },
        // 4. Max Hz Column
        {
          data: "value.maxHz",
          className: "col-value",
          render: function (data, type, row) {
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="maxHz" placeholder="Enter Numerical Value" type="number" style="width:60px" value="${data ?? ''}">`
              : `${data ?? "-"}`;
          }
        },
        // 5. Min Hz Column
        {
          data: "value.minHz",
          className: "col-value",
          render: function (data, type, row) {
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="minHz" placeholder="Enter Numerical Value" type="number" style="width:60px" value="${data ?? ''}">`
              : `${data ?? "-"}`;
          }
        },
        // 6. Hold (s) Column
        {
          data: "value.holdMs",
          className: "col-value",
          render: function (data, type, row) {
            const value = data === null || data === undefined || data === "" ? "" : Number(data) / 1000;
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="holdMs" placeholder="Enter Numerical Value" type="number" step="0.001" style="width:80px" value="${value}">`
              : value === "" ? "-" : `${value}`;
          }
        },
        // 7. Step Hz Column
        {
          data: "value.stepHz",
          className: "col-value",
          render: function (data, type, row) {
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="stepHz" placeholder="Enter Numerical Value" type="number" style="width:60px" value="${data ?? ''}">`
              : `${data ?? "-"}`;
          }
        },
        // 8. Target Column
        {
          data: "value.target",
          className: "col-value",
          render: function (data, type, row) {
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="target" placeholder="Enter Numerical Value" type="number" step="0.1" style="width:60px" value="${data ?? ''}">`
              : `${data ?? "-"}`;
          }
        },
        // 9. Reading Column
        {
          data: "value.target",
          className: "col-value text-center",
          render: function (data, type, row) {
            let value = null;
            if (row.key === 'ct_fan.cws_controller') {
              value = telemeryData['cws_cwHeader'];
            } else if (row.key === 'cwp.delta_t_controller') {
              value = telemeryData['deltaT_cwHeader'];
            } else if (row.key === 'chwp.delta_t_controller') {
              value = telemeryData['deltaT_chwHeader'];
            }
            if (value == null) return '-';

            return value.toFixed(2);
          }
        },
        // 9. Dwell (s) Column
        {
          data: "value.dwellMs",
          className: "col-value",
          render: function (data, type, row) {
            const value = data === null || data === undefined || data === "" ? "" : Number(data) / 1000;
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="dwellMs" placeholder="Enter Numerical Value" type="number" step="0.001" style="width:80px" value="${value}">`
              : value === "" ? "-" : `${value}`;
          }
        },
        // 10. Deadband Column
        {
          data: "value.deadband",
          className: "col-value",
          render: function (data, type, row) {
            return row.isEditingRow
              ? `<input class="ptp-input ptp-field" data-field="deadband" placeholder="Enter Numerical Value" type="number" step="0.1" style="width:60px" value="${data ?? ''}">`
              : `${data ?? "-"}`;
          }
        },
        // 11. Action Buttons Column
        {
          data: null,
          className: "col-action dt-body-center",
          render: function (_, __, row) {
            if (row.isLoading) {
              return `<i class="fa fa-spinner fa-spin"></i>`;
            }
            if (row.isEditingRow) {
              return `
              <div class="ptp-actions">
                <button class="ptp-btn ptp-btn-icon ptp-btn-save saveSetting btn-secondary" type="button" title="Save" aria-label="Save" disabled><i class="fa fa-check" aria-hidden="true"></i></button>
                <button class="ptp-btn ptp-btn-icon ptp-btn-cancel cancelSetting btn-secondary" type="button" title="Cancel" aria-label="Cancel"><i class="fa fa-times" aria-hidden="true"></i></button>
              </div>
            `;
            }
            return `<button class="ptp-btn ptp-btn-icon editSetting btn-secondary" type="button" title="Edit" aria-label="Edit" ${row.isDisableEdit ? "disabled" : ""}><i class="fa fa-pencil" aria-hidden="true"></i></button>`;
          }
        }
      ]
    });

    table.clear().rows.add(data).draw(false);
    resetEvents();

    function patch(url, data) {
      return new Promise((resolve, reject) => {
        $.ajax({
          url,
          dataType: 'json',
          type: 'post',
          contentType: 'application/json',
          data: JSON.stringify(data),
          processData: false,
          success: function (response, textStatus, jQxhr) {
            resolve(response);
          },
          error: function (jqXhr, textStatus, errorThrown) {
            reject({ response: jqXhr.responseText, error: errorThrown });
          },
        });
      });
    }

    function put(url, data) {
      return new Promise((resolve, reject) => {
        $.ajax({
          url,
          dataType: 'json',
          type: 'put',
          contentType: 'application/json',
          data: JSON.stringify(data),
          processData: false,
          success: function (response, textStatus, jQxhr) {
            resolve(response);
          },
          error: function (jqXhr, textStatus, errorThrown) {
            reject({ response: jqXhr.responseText, error: errorThrown });
          },
        });
      });
    }

    function get(url) {
      return new Promise((resolve, reject) => {
        $.ajax({
          url,
          dataType: 'json',
          type: 'get',
          processData: false,
          success: function (response, textStatus, jQxhr) {
            resolve(response);
          },
          error: function (jqXhr, textStatus, errorThrown) {
            reject({ response: jqXhr.responseText, error: errorThrown });
          },
        });
      });
    }

    function del(url) {
      return new Promise((resolve, reject) => {
        $.ajax({
          url,
          dataType: 'json',
          type: 'post',
          processData: false,
          success: function (response, textStatus, jQxhr) {
            resolve(response);
          },
          error: function (jqXhr, textStatus, errorThrown) {
            reject({ response: jqXhr.responseText, error: errorThrown });
          },
        });
      });
    }

    function resetEvents() {
      const tableEl = $("#ptp-table-7");
      tableEl.off();

      function serializeEditInputs(tr) {
        return tr.find(".ptp-field").map(function () {
          if ($(this).is(":checkbox")) return $(this).is(":checked") ? "1" : "0";
          return String($(this).val() ?? "");
        }).get().join("");
      }

      function refreshSaveButton(tr) {
        const data = table.row(tr).data();
        const initial = data && data._editSnapshot;
        tr.find("button.saveSetting").prop("disabled", initial === undefined || serializeEditInputs(tr) === initial);
      }

      tableEl.on("input change", ".ptp-field", function () {
        refreshSaveButton($(this).closest("tr"));
      });

      tableEl.on("click", "button.editSetting", function () {
        const tr = $(this).closest("tr");
        const row = table.row(tr);
        const data = row.data();

        if (isEdit) return alert("Can only edit one record at a time");

        isEdit = true;
        data.isEditingRow = true;
        row.invalidate().draw(false);
        const editTr = $(row.node());
        data._editSnapshot = serializeEditInputs(editTr);
        refreshSaveButton(editTr);
      });

      tableEl.on("click", "button.saveSetting", async function () {
        const tr = $(this).closest("tr");
        const row = table.row(tr);
        const data = row.data();
        let reason = "";
        while (true) {
          reason = prompt("Remark for this change:", reason);
          if (reason === null) return;
          reason = reason.trim();
          if (reason) break;
          alert("Remark is required.");
        }
        data.isLoading = true;

        const handleValidationError = (message) => {
          alert(message);
          data.isLoading = false;
        };

        const valueObject = {};
        let isValid = true;

        tr.find('.ptp-field').each(function () {
          const fieldName = $(this).data('field');
          const fieldType = $(this).data('type');
          let fieldValue = $(this).val();

          if (fieldType === 'boolean') {
            valueObject[fieldName] = $(this).is(':checked');
            return;
          }

          // Cast string numbers to real JS numbers if filled
          if (fieldValue !== "") {
            const parsedValue = parseFloat(fieldValue, 10);

            if (isNaN(parsedValue)) {
              handleValidationError(`Please enter a valid number for ${fieldName}.`);
              isValid = false;
              return false;
            }
            // 2. Check if the number is negative
            if (parsedValue < 0) {
              handleValidationError(`Please enter a number greater than or equal to 0 for ${fieldName}.`);
              isValid = false;
              return false;
            }
            fieldValue = fieldName.endsWith('Ms') ? Math.round(parsedValue * 1000) : parsedValue;
          } else {
            fieldValue = null;
          }

          valueObject[fieldName] = fieldValue;
        });

        if (!isValid) {
          return;
        }

        // Compile payload using the updated layout properties
        const payload = {
          scope: data.scope,
          equipmentKind: data.equipment_kind,
          equipmentId: data.equipment_id,
          key: data.key,
          value: valueObject,
          reason: reason,
        };


        try {
          if (JSON.stringify(data.value) !== JSON.stringify(payload.value)) {
            await patch(`${HOST}/params/value`, payload);
          }
          Object.assign(data, {
            isEditingRow: false,
            isLoading: false,
          });

          isEdit = false;
          context.grafana.refresh();
          setTimeout(() => {
            alert("Updated!");
          }, 100);
        } catch (e) {
          alert(`Error: ${e.response ? e.response.data.message : e.message}`);
          console.error(e);
        }

      });

      tableEl.on("click", "button.cancelSetting", function () {
        const tr = $(this).closest("tr");
        const row = table.row(tr);
        const data = row.data();
        data.isEditingRow = false;
        isEdit = false;
        row.invalidate().draw(false);
      });

    }
  })
});

