  font-weight: 400 !important;
  padding: 7px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}


.ptp-btn:disabled,
.ptp-btn[disabled] {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(1);
}

.ptp-btn-save:disabled,
.ptp-btn-save[disabled] {
  background: #d1d5db !important;
  color: #6b7280 !important;
}
// .ptp-btn:hover { background: #f4f4f2; border-color: #bcbcb4; }

.ptp-btn-save {
  font-weight: 400;
  padding: 7px 14px;
}
// .ptp-btn-save:hover { background: #000; }

.ptp-btn-cancel {
  font-size: 18px;
  line-height: 1;
  padding: 7px 14px;
}

.ptp-note {
  margin-top: 14px;
  font-size: 12.5px;
  font-family: Inter, Helvetica, Arial, sans-serif;
}

.ptp-btn-icon {
  width: 34px;
  height: 34px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.ptp-btn-icon .fa {
  font-size: 14px;
  line-height: 1;
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
.ptp-card:where(.dark) {
  color-scheme: dark;
}
*:where(.ptp-card.dark) .ptp-hint {
  color: #b0b0be;
}
*:where(.ptp-card.dark) .ptp-input {
  border: 1.5px solid #6e7480;
}
*:where(.ptp-card.dark) .ptp-btn-save:disabled,
*:where(.ptp-card.dark) .ptp-btn-save[disabled] {
  background: #2c3036 !important;
  color: #b0b0be !important;
}
